package com.example.article.controller;

import com.example.article.dto.ArticleCreateRequest;
import com.example.article.dto.ArticlePatchRequest;
import com.example.article.dto.ArticleQuery;
import com.example.article.dto.ArticleResponse;
import com.example.article.dto.ArticleUpdateRequest;
import com.example.article.service.ArticleService;
import com.example.common.ApiResponse;
import com.example.common.PageResult;
import jakarta.validation.Valid;
import jakarta.validation.constraints.Min;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PatchMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * 一个 Controller 里放齐五种动词。
 *
 * 读这份代码的顺序建议：
 *   先看每个方法上面的「语义」注释，明确它该干什么；
 *   再看它返回什么、入参是什么，就明白为什么必须这样做。
 *
 * 一条总原则：动词不是标签，是契约。
 *   误用动词（例如用 GET 做删除）会让浏览器预取、CDN、爬虫、重试中间件
 *   在不该动手的时候动手 —— 这些中间件只认动词，不读你的文档。
 */
@Validated
@RestController
@RequestMapping("/api/v1/articles")
public class ArticleController {

    private final ArticleService articleService;

    public ArticleController(ArticleService articleService) {
        this.articleService = articleService;
    }

    // ─────────────────────────────────────────────────────────────
    // GET：读取。必须幂等（重复调用结果一致）、必须无副作用。
    // 成功 200。查询条件走 query string，不进请求体 —— GET 带 body 会让
    // 缓存、日志、代理的行为全部变得不可预测。
    // ─────────────────────────────────────────────────────────────

    /** 列表查询。返回结构化分页契约，不是裸 List。 */
    @GetMapping
    public ApiResponse<PageResult<ArticleResponse>> list(@Valid ArticleQuery query) {
        return ApiResponse.ok(articleService.page(query));
    }

    /** 单条查询。资源不存在 → 404，由全局处理器统一出口，Controller 内不判空。 */
    @GetMapping("/{id}")
    public ApiResponse<ArticleResponse> detail(@PathVariable @Min(value = 1, message = "id 必须为正整数") long id) {
        return ApiResponse.ok(articleService.detail(id));
    }

    // ─────────────────────────────────────────────────────────────
    // POST：创建 / 触发动作。非幂等 —— 同一份报文提交两次会产生两条资源，
    // 这是语义要求，不是缺陷。若业务上需要防重，必须靠业务唯一键，
    // 而不是指望调用方「不会重复提交」。
    // 成功建议 201 + 返回新建资源标识。
    // ─────────────────────────────────────────────────────────────

    /** 创建文章。返回新资源 id，让调用方能直接跳详情，省掉一次查询。 */
    @PostMapping
    public ApiResponse<Long> create(@Valid @RequestBody ArticleCreateRequest request) {
        return ApiResponse.created(articleService.create(request));
    }

    // ─────────────────────────────────────────────────────────────
    // PUT：全量替换。幂等 —— 同一份报文提交 N 次，最终状态一致。
    // 语义上是「用我给的这份完整表示替换掉原资源」，因此：
    //   字段必须完整（缺字段意味着置空，而不是保持原值）；
    //   不存在的资源可以按业务决定是新建（upsert）还是 404。
    // 这里选择 404：隐式的 upsert 会让调用方分不清「改了」还是「建了」。
    // ─────────────────────────────────────────────────────────────

    /** 全量更新。注意 request 里的字段必须完整覆盖可写字段。 */
    @PutMapping("/{id}")
    public ApiResponse<Void> replace(@PathVariable @Min(value = 1, message = "id 必须为正整数") long id,
                                     @Valid @RequestBody ArticleUpdateRequest request) {
        articleService.replace(id, request);
        return ApiResponse.ok();
    }

    // ─────────────────────────────────────────────────────────────
    // PATCH：局部修改。同样是幂等的，但语义是「只改我给的字段，其余保持不动」。
    // 与 PUT 的关键区别在「缺席字段」的解释：
    //   PUT   缺席 = 置空
    //   PATCH 缺席 = 不改
    // 因此 PATCH 的入参必须允许字段为 null，且必须能区分
    // 「没传这个字段」与「显式传了 null 想把它清空」——
    // 这是 PATCH 最容易做错的地方，见 ArticlePatchRequest。
    // ─────────────────────────────────────────────────────────────

    /** 局部更新。刻意加了 /publish 子资源，表达「发布」这个状态迁移动作。 */
    @PatchMapping("/{id}")
    public ApiResponse<Void> patch(@PathVariable @Min(value = 1, message = "id 必须为正整数") long id,
                                   @Valid @RequestBody ArticlePatchRequest request) {
        articleService.patch(id, request);
        return ApiResponse.ok();
    }

    // ─────────────────────────────────────────────────────────────
    // DELETE：删除。必须幂等 —— 删一个不存在的记录不应报 404 还是 200 反复横跳，
    // 这里统一返回成功，因为「最终状态是它不存在」这个事实已经达成。
    // 返回体留空（Void），不要返回被删对象的完整内容：
    // 那等于在响应里又泄露一份已删除数据，也让响应体白白变大。
    // ─────────────────────────────────────────────────────────────

    /** 删除。业务上采用逻辑删除，见 ArticleRepository.deleteById。 */
    @DeleteMapping("/{id}")
    public ApiResponse<Void> delete(@PathVariable @Min(value = 1, message = "id 必须为正整数") long id) {
        articleService.delete(id);
        return ApiResponse.ok();
    }
}

package com.example.article.dto;

import com.example.article.domain.ArticleStatus;
import jakarta.validation.constraints.Size;
import java.util.Optional;

/**
 * 局部更新（PATCH）的入参 —— 这份代码专门解决一个容易做错的问题：
 * 「没传这个字段」和「显式传了 null 要把字段清空」，怎么区分？
 *
 * 常见错误做法（三种都有问题）：
 *   1. 全用 String 字段 —— 无法区分，null 被一律当作「不改」，
 *      于是「清空摘要」这个需求永远做不了；
 *   2. 用包装类型 + null 判断 —— 语义永远含糊，调用方也不知道 null 是什么意思；
 *   3. 加一个 fieldMask 数组 —— 能用，但把复杂度推给了每个调用方。
 *
 * 正确做法：用 Optional<T> 显式表达三态。
 *   Optional.empty()          → 未传，保持原值
 *   Optional.of(null)         → 显式传 null，清空
 *   Optional.of(value)        → 修改为新值
 *
 * 注意：Jackson 默认不会把缺失字段映射成 Optional.empty()，需要
 * 配置 Jdk8Module 并把字段默认值设为 Optional.empty()，
 * 见项目骨架蓝图里的 JacksonConfig。
 */
public class ArticlePatchRequest {

    /** 标题：可不传；传了就必须满足长度约束。 */
    private Optional<@Size(min = 1, max = 120, message = "标题长度须在 1~120 之间") String> title =
            Optional.empty();

    /** 摘要：允许显式清空，因此这里是 Optional<String> 而不是 String。 */
    private Optional<@Size(max = 500, message = "摘要不能超过 500 字") String> summary = Optional.empty();

    /** 状态：只在状态迁移时传，取值由枚举收敛。 */
    private Optional<ArticleStatus> status = Optional.empty();

    public Optional<String> getTitle() {
        return title;
    }

    public void setTitle(Optional<String> title) {
        this.title = title == null ? Optional.empty() : title;
    }

    public Optional<String> getSummary() {
        return summary;
    }

    public void setSummary(Optional<String> summary) {
        this.summary = summary == null ? Optional.empty() : summary;
    }

    public Optional<ArticleStatus> getStatus() {
        return status;
    }

    public void setStatus(Optional<ArticleStatus> status) {
        this.status = status == null ? Optional.empty() : status;
    }
}

package com.example.article.service;

import com.example.article.domain.Article;
import com.example.article.dto.ArticlePatchRequest;
import com.example.article.repository.ArticleRepository;
import com.example.common.exception.BizException;
import java.util.Optional;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * 只展示 PATCH 在 Service 侧怎么落地 —— PUT 与 PATCH 的差异最终都体现在这里。
 *
 * 核心写法：Optional 的三种状态直接映射成三种动作，
 * 不需要 if (x != null) 这种含糊判断，读代码时不用去猜 null 是什么意思。
 */
@Service
public class ArticlePatchService {

    private static final Logger log = LoggerFactory.getLogger(ArticlePatchService.class);

    private final ArticleRepository articleRepository;

    public ArticlePatchService(ArticleRepository articleRepository) {
        this.articleRepository = articleRepository;
    }

    @Transactional(rollbackFor = Exception.class)
    public void patch(long id, ArticlePatchRequest request) {
        Article article = articleRepository.findById(id);
        if (article == null) {
            throw new BizException("ARTICLE_NOT_FOUND", "文章不存在：" + id);
        }

        // 未传 → 保持原值；传了 null → 清空；传了值 → 更新
        request.getTitle().ifPresent(article::setTitle);
        request.getSummary().ifPresent(article::setSummary);
        request.getStatus().ifPresent(article::setStatus);

        if (articleRepository.update(article) == 0) {
            throw new BizException("ARTICLE_CONCURRENT_MODIFIED", "文章已被修改，请刷新后重试");
        }
        log.info("文章已局部更新 id={}", id);
    }

    /**
     * 反面示例：如果这里用 String 而不是 Optional，
     * 就只能写成下面这样 —— 语义立刻丢失，而且「清空摘要」永远做不到。
     *
     *   if (request.getSummary() != null) {
     *       article.setSummary(request.getSummary());   // 那传 null 想清空怎么办？
     *   }
     */
    private void badExampleNeverCalled(Article article, String summary) {
        if (summary != null) {
            article.setSummary(summary);
        }
    }

    /** 一个 Optional 转 null 的辅助写法，供需要写入数据库时使用。 */
    public static <T> T orNull(Optional<T> value) {
        return value.orElse(null);
    }
}

package com.example.article.domain;

/**
 * 状态用枚举，不用 int 常量，也不直接收字符串。
 *
 * 为什么：入参一旦是 String，"PUBLISHED" 拼成 "PUBLISH" 只能在业务代码里
 * 用 if 去兜，而且每个接口都要兜一遍。枚举把非法值挡在反序列化阶段 ——
 * 这是最前端的一道，也是最省事的一道。
 *
 * 数据库里存的可以是 int（省空间）或 varchar（可读），
 * 但无论哪种，都必须在 Repository 层做一次显式转换，
 * 不允许让枚举序数（ordinal）隐式落库 ——
 * 那样只要有人在中间插一个新枚举值，全部历史数据的含义就集体错位。
 */
public enum ArticleStatus {

    /** 草稿。 */
    DRAFT(1),

    /** 已发布。 */
    PUBLISHED(2),

    /** 已下线。 */
    OFFLINE(3);

    private final int code;

    ArticleStatus(int code) {
        this.code = code;
    }

    public int getCode() {
        return code;
    }

    /** 显式转换，禁止用 ordinal()。 */
    public static ArticleStatus ofCode(int code) {
        for (ArticleStatus status : values()) {
            if (status.code == code) {
                return status;
            }
        }
        throw new IllegalArgumentException("未知的文章状态码：" + code);
    }
}
